package lu.bourse.engine.explanation;

import lu.bourse.engine.calendar.MarketCalendarService;
import lu.bourse.engine.market.WatchlistService;
import lu.bourse.engine.provider.DatabaseIntegrationSupport;
import lu.bourse.engine.social.*;
import org.junit.jupiter.api.*;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.test.context.bean.override.mockito.MockitoBean;
import org.springframework.web.server.ResponseStatusException;
import java.math.BigDecimal;
import java.sql.*;
import java.time.*;
import java.util.*;
import static org.assertj.core.api.Assertions.*;
import static org.mockito.Mockito.when;

@SpringBootTest
class ExplanationIntegrationTest extends DatabaseIntegrationSupport {
    @Autowired ExplanationService service;@Autowired SocialSignalService social;@Autowired WatchlistService watchlist;@Autowired JdbcTemplate db;@Autowired MarketCalendarService calendars;
    @MockitoBean Clock clock;long asset;static final Instant NOW=Instant.parse("2026-11-19T15:00:00Z");
    @BeforeEach void setup(){when(clock.instant()).thenReturn(NOW);when(clock.getZone()).thenReturn(ZoneOffset.UTC);for(String t:List.of("market_news","financial_facts","company_profiles","asset_provider_symbols","provider_price_observations","market_candles","assets","import_jobs","provider_api_calls"))db.update("DELETE FROM "+t);asset=watchlist.register(new WatchlistService.Entry("TEST","Test","STOCK","USD","TEST","US","America/New_York","09:30","16:00",true));}
    long rules(int technical,int financial,int information){return service.createRules(new ExplanationService.NewRules("TEST_"+UUID.randomUUID(),new ExplanationService.Rules(technical,financial,information,new BigDecimal("3"),new BigDecimal("30"),new BigDecimal("70"))));}
    void fact(String concept,String value,int year,String filed,String accession,String unit){db.update("INSERT INTO financial_facts(asset_id,concept,value,unit,period_start,period_end,filed_date,form_type,accession_number,source) VALUES (?,?,?,?,?,?,?,'10-K',?,'TEST')",asset,concept,new BigDecimal(value),unit,java.sql.Date.valueOf(year+"-01-01"),java.sql.Date.valueOf(year+"-12-31"),java.sql.Date.valueOf(filed),accession);}
    void statements(){fact("Revenues","100",2024,"2025-02-01","2024","USD");fact("NetIncomeLoss","18",2024,"2025-02-01","2024","USD");fact("Revenues","100",2025,"2026-02-01","2025","USD");fact("NetIncomeLoss","14",2025,"2026-02-01","2025","USD");}
    void bars(String tf,int seconds,BigDecimal base){for(int i=40;i>=1;i--){var time=NOW.minusSeconds((long)i*seconds);BigDecimal price=base.add(BigDecimal.valueOf(40-i));db.update("INSERT INTO market_candles(asset_id,timeframe,open_time,open_price,high_price,low_price,close_price,volume,provider) VALUES (?,?,?,?,?,?,?,100,'TEST')",asset,tf,Timestamp.from(time),price,price,price,price);}}
    @Test void financialRuleExplainsTheFormulaValuesAndNegativeContribution(){statements();var r=service.calculate("TEST",ExplanationService.Horizon.YEAR,rules(0,20,0));assertThat(r.score()).isEqualByComparingTo("30");var factor=r.factors().stream().filter(f->f.key().equals("NET_MARGIN_CHANGE")).findFirst().orElseThrow();assertThat(factor.points()).isEqualByComparingTo("-20");assertThat(factor.explanation()).contains("Marge nette","-4.00000000");assertThat(factor.evidence().toString()).contains("revenueFact","incomeFact","accession_number");}
    @Test void futureFilingsAndMismatchedUnitsCannotProduceAnInventedMargin(){statements();db.update("DELETE FROM financial_facts WHERE period_end='2025-12-31'");fact("Revenues","100",2025,"2026-11-20","future","USD");fact("NetIncomeLoss","14",2025,"2026-11-20","future","USD");var r=service.calculate("TEST",ExplanationService.Horizon.YEAR,rules(0,20,0));assertThat(r.score()).isNull();assertThat(r.coverageScore()).isZero();}
    @Test void sameDayFilingIsConservativelyExcludedWithoutAnExactPublicationTime(){statements();db.update("UPDATE financial_facts SET filed_date='2026-11-19' WHERE period_end='2025-12-31'");assertThat(service.calculate("TEST",ExplanationService.Horizon.YEAR,rules(0,20,0)).score()).isNull();}
    @Test void incompatibleRestatementsAreNotMixedAcrossAccessions(){statements();fact("Revenues","120",2025,"2026-03-01","amended-revenue-only","USD");assertThat(service.calculate("TEST",ExplanationService.Horizon.YEAR,rules(0,20,0)).score()).isNull();}
    @Test void immutableSnapshotsKeepOldEvidenceAndDeltasSumExactly(){statements();long version=rules(0,20,0);var first=service.calculate("TEST",ExplanationService.Horizon.YEAR,version);String frozen=db.queryForObject("SELECT result_json FROM explanation_snapshots WHERE id=?",String.class,first.id());fact("Revenues","100",2025,"2026-03-01","amended","USD");fact("NetIncomeLoss","25",2025,"2026-03-01","amended","USD");var second=service.calculate("TEST",ExplanationService.Horizon.YEAR,version);assertThat(second.scoreChange()).isEqualByComparingTo("40");assertThat(second.contributionChanges().values().stream().reduce(BigDecimal.ZERO,BigDecimal::add)).isEqualByComparingTo(second.scoreChange());assertThat(db.queryForObject("SELECT result_json FROM explanation_snapshots WHERE id=?",String.class,first.id())).isEqualTo(frozen);assertThat(service.get(first.id()).get("id")).isNotNull();}
    @Test void everyHorizonUsesItsOwnSeriesAndSeasonalityStaysExplicitlyExploratory(){bars("15m",900,new BigDecimal("100"));bars("1h",3600,new BigDecimal("200"));bars("1d",86400,new BigDecimal("300"));long version=rules(20,0,0);for(var h:ExplanationService.Horizon.values()){var r=service.calculate("TEST",h,version);var technical=r.factors().stream().filter(f->f.key().equals("TECH_MACD")).findFirst().orElseThrow();assertThat(((Map<?,?>)technical.evidence()).get("timeframe")).isEqualTo(switch(h){case DAY->"15m";case MONTH->"1h";case YEAR->"1d";});assertThat(r.factors().stream().filter(f->f.key().equals("SEASONALITY")).findFirst().orElseThrow().points()).isZero();assertThat(r.score()).isBetween(BigDecimal.ZERO,new BigDecimal("100"));}}
    @Test void newsCanChangeTheScoreWithOriginalSourcesAndAttribution(){long version=rules(0,0,20);long actor=social.actor(new SocialSignalService.Actor("Test official","Policy decision maker","OFFICIAL_WEB","test-official",true,"https://example.org/identity"));social.profile(actor,new SocialSignalService.Profile(SocialScoring.Topic.TARIFFS,100,NOW.minusSeconds(86400),null,"Synthetic authority"));long publication=social.publication(new SocialSignalService.Publication(actor,"p1","Synthetic announcement on tariffs","https://example.org/original",NOW));long event=social.event(new SocialSignalService.Event("tariff-test","Test tariffs",SocialScoring.Topic.TARIFFS,SocialScoring.Kind.ANNOUNCEMENT,SocialScoring.Confirmation.OFFICIAL_DOCUMENT,"https://example.org/official",List.of(publication)));social.assess(event,new SocialSignalService.Assessment("TEST",SocialScoring.Direction.NEGATIVE,100,100,100,100,SocialScoring.Horizon.DAYS,"Synthetic import cost exposure"));var r=service.calculate("TEST",ExplanationService.Horizon.DAY,version);assertThat(r.score()).isEqualByComparingTo("31");assertThat(r.factors().stream().filter(f->f.category().equals("INFORMATION")).findFirst().orElseThrow().evidence().toString()).contains("https://example.org/original","Synthetic import cost exposure");}
    @Test void ruleChangesCreateNewVersionsAndNeverOverwriteDefaultOrPreviousRules(){assertThatThrownBy(()->service.createRules(new ExplanationService.NewRules("DEFAULT_DAY_V1",new ExplanationService.Rules(10,10,10,BigDecimal.ONE,BigDecimal.TEN,new BigDecimal("90"))))).isInstanceOf(ResponseStatusException.class);assertThatThrownBy(()->rules(Integer.MAX_VALUE,0,0)).isInstanceOf(ResponseStatusException.class);assertThatThrownBy(()->rules(0,0,0)).isInstanceOf(ResponseStatusException.class);statements();var first=service.calculate("TEST",ExplanationService.Horizon.YEAR,rules(0,20,0));var second=service.calculate("TEST",ExplanationService.Horizon.YEAR,rules(0,10,0));assertThat(second.rulesetChanged()).isTrue();assertThat(second.previousSnapshotId()).isEqualTo(first.id());assertThat(second.scoreChange()).isEqualByComparingTo("10");}
    @Test void noDataDoesNotBecomeANeutralScore(){var r=service.calculate("TEST",ExplanationService.Horizon.MONTH,null);assertThat(r.score()).isNull();assertThat(r.coverageScore()).isZero();assertThat(r.quoteQuality().status()).isEqualTo("DATA_INCOMPLETE");}
    @Test void cappedNewsContributionsSumExactlyAndRoundingNeverGivesPointsToAnUnknownDirection(){
        long actor=social.actor(new SocialSignalService.Actor("Test official","Policy role","OFFICIAL_WEB","bounded-test",true,"https://example.org/identity"));
        social.profile(actor,new SocialSignalService.Profile(SocialScoring.Topic.TARIFFS,100,NOW.minusSeconds(86400),null,"Synthetic authority"));
        long publication=social.publication(new SocialSignalService.Publication(actor,"bounded","Synthetic separate policy scenarios","https://example.org/original",NOW));long unknown=0;
        for(int i=0;i<4;i++){long event=social.event(new SocialSignalService.Event("bounded-"+i,"Synthetic independent event "+i,SocialScoring.Topic.TARIFFS,SocialScoring.Kind.ANNOUNCEMENT,SocialScoring.Confirmation.OFFICIAL_DOCUMENT,"https://example.org/evidence",List.of(publication)));social.assess(event,new SocialSignalService.Assessment("TEST",i==3?SocialScoring.Direction.UNKNOWN:SocialScoring.Direction.POSITIVE,100,100,100,100,SocialScoring.Horizon.DAYS,"Synthetic exposure"));if(i==3)unknown=event;}
        var result=service.calculate("TEST",ExplanationService.Horizon.DAY,rules(0,0,17));assertThat(result.score()).isEqualByComparingTo("67");
        assertThat(result.factors().stream().filter(f->f.category().equals("INFORMATION")).map(ExplanationService.Factor::points).reduce(BigDecimal.ZERO,BigDecimal::add)).isEqualByComparingTo("17");
        String key="EVENT_"+unknown;assertThat(result.factors().stream().filter(f->f.key().equals(key)).findFirst().orElseThrow().points()).isZero();
    }
}
